CREATE TABLE IF NOT EXISTS settings (id int PRIMARY KEY CHECK(id=1), value jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, phone text NOT NULL, dob date NOT NULL, consent_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS staff (id text PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, password_hash text, role text NOT NULL CHECK(role IN ('admin','manager','promoter')), status text NOT NULL DEFAULT 'invited', totp_secret text);
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, principal_id text NOT NULL, principal_type text NOT NULL, csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS login_tokens (token_hash text PRIMARY KEY, principal_id text NOT NULL, kind text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS events (id text PRIMARY KEY, title text NOT NULL, description text NOT NULL, lineup text NOT NULL, poster_url text NOT NULL DEFAULT '', starts_at timestamptz NOT NULL, doors_at timestamptz NOT NULL, capacity int NOT NULL CHECK(capacity BETWEEN 1 AND 700), status text NOT NULL CHECK(status IN ('draft','published','cancelled')), created_by text REFERENCES staff(id));
CREATE TABLE IF NOT EXISTS ticket_tiers (id text PRIMARY KEY, event_id text NOT NULL REFERENCES events(id), name text NOT NULL, kind text NOT NULL CHECK(kind IN ('ticket','table')), party_type text NOT NULL CHECK(party_type IN ('female','couple','table')), seats int NOT NULL CHECK(seats>0), price_paise int NOT NULL CHECK(price_paise>=0), quantity int NOT NULL CHECK(quantity>0), remaining int NOT NULL CHECK(remaining>=0 AND remaining<=quantity), max_per_order int NOT NULL CHECK(max_per_order BETWEEN 1 AND 4), sale_starts_at timestamptz NOT NULL, sale_ends_at timestamptz NOT NULL, perks text NOT NULL DEFAULT '', sort_order int NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS holds (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), tier_id text NOT NULL REFERENCES ticket_tiers(id), qty int NOT NULL CHECK(qty>0), expires_at timestamptz NOT NULL, status text NOT NULL CHECK(status IN ('active','converted','expired')), request_key text NOT NULL, UNIQUE(user_id,request_key));
CREATE TABLE IF NOT EXISTS orders (id text PRIMARY KEY, user_id text REFERENCES users(id), event_id text NOT NULL REFERENCES events(id), tier_id text NOT NULL REFERENCES ticket_tiers(id), hold_id text UNIQUE REFERENCES holds(id), qty int NOT NULL CHECK(qty>0), status text NOT NULL DEFAULT 'pending', subtotal_paise int NOT NULL, cover_paise int NOT NULL DEFAULT 0, fee_paise int NOT NULL DEFAULT 0, gst_paise int NOT NULL DEFAULT 0, total_paise int NOT NULL, razorpay_order_id text UNIQUE, razorpay_payment_id text UNIQUE, holder_names jsonb NOT NULL, phone text NOT NULL, notes text NOT NULL DEFAULT '', policy_accepted_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tickets (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), holder_name text NOT NULL, qr_payload text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'valid');
CREATE TABLE IF NOT EXISTS webhook_events (event_id text PRIMARY KEY, type text NOT NULL, processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refunds (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), payment_id text UNIQUE NOT NULL, amount_paise int NOT NULL, status text NOT NULL DEFAULT 'pending', reason text NOT NULL, provider_id text, attempts int NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS guestlist_entries (id text PRIMARY KEY, event_id text NOT NULL REFERENCES events(id), name text NOT NULL, phone text NOT NULL, party_type text NOT NULL CHECK(party_type IN ('female','couple')), plus_count int NOT NULL CHECK(plus_count>=0), notes text NOT NULL, added_by text NOT NULL REFERENCES staff(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,phone));
CREATE TABLE IF NOT EXISTS audit_log (id text PRIMARY KEY, staff_id text, action text NOT NULL, entity text NOT NULL, entity_id text, diff jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox (id text PRIMARY KEY, recipient text NOT NULL, subject text NOT NULL, html text NOT NULL, status text NOT NULL DEFAULT 'pending', attempts int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE outbox ADD COLUMN IF NOT EXISTS attachments jsonb NOT NULL DEFAULT '[]';
CREATE TABLE IF NOT EXISTS rate_limits (key text PRIMARY KEY, count int NOT NULL, resets_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS tiers_event ON ticket_tiers(event_id);
CREATE INDEX IF NOT EXISTS holds_expiry ON holds(expires_at) WHERE status='active';
CREATE INDEX IF NOT EXISTS holds_user ON holds(user_id,tier_id);
CREATE INDEX IF NOT EXISTS orders_user ON orders(user_id);
CREATE INDEX IF NOT EXISTS orders_event ON orders(event_id);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
